const updates=[{"file":"src/App.tsx","before":"cd37207950b4686da2cfbaa444f66e712fc1e44aff74b80f2aaf9d981e4261a8","next":"import { useEffect } from 'react';\nimport { CartProvider } from '@/context/CartContext';\nimport { PrescriptionBasketProvider } from '@/context/PrescriptionBasketContext';\nimport { MemberProvider } from '@/context/MemberContext';\nimport { CustomerAuthProvider } from '@/context/CustomerAuthContext';\nimport { useRouter } from '@/router';\nimport { Header } from '@/components/Header';\nimport { Footer } from '@/components/Footer';\nimport { CartDrawer } from '@/components/CartDrawer';\nimport { PrescriptionBasketDrawer } from '@/components/PrescriptionBasketDrawer';\nimport { HomePage } from '@/pages/HomePage';\nimport { GoalsPage } from '@/pages/GoalsPage';\nimport { GoalPage } from '@/pages/GoalPage';\nimport { SectionPage } from '@/pages/SectionPage';\nimport { BestSellersPage } from '@/pages/BestSellersPage';\nimport { ProductPage } from '@/pages/ProductPage';\nimport { CheckoutPage } from '@/pages/CheckoutPage';\nimport { GrouponPage } from '@/pages/GrouponPage';\nimport { OrderPaymentInstructionsPage } from '@/pages/OrderPaymentInstructionsPage';\nimport { KashuCardResultPage } from '@/pages/KashuCardResultPage';\nimport { SuccessPage } from '@/pages/SuccessPage';\nimport { CancelPage } from '@/pages/CancelPage';\nimport { TrackPage } from '@/pages/TrackPage';\nimport { AboutPage } from '@/pages/AboutPage';\nimport { FaqPage } from '@/pages/FaqPage';\nimport { SubscriptionsPage } from '@/pages/SubscriptionsPage';\nimport { AlaCartePage } from '@/pages/AlaCartePage';\nimport { RefundPolicyPage } from '@/pages/RefundPolicyPage';\nimport { ContactPage } from '@/pages/ContactPage';\nimport { ShopAllPage } from '@/pages/ShopAllPage';\nimport { PrivacyPolicyPage } from '@/pages/PrivacyPolicyPage';\nimport { TermsPage } from '@/pages/TermsPage';\nimport { ConcernPage } from '@/pages/ConcernPage';\nimport { ShippingPolicyPage } from '@/pages/ShippingPolicyPage';\nimport { BUILD_VERSION } from '@/buildVersion';\n\n// Keep the deploy marker in the customer bundle for staging sync verification (not rendered).\n(globalThis as typeof globalThis & { __MBM_BUILD_VERSION__?: string }).__MBM_BUILD_VERSION__ =\n  BUILD_VERSION;\nimport { AccessibilityPage } from '@/pages/AccessibilityPage';\nimport { ConsumerDataPage } from '@/pages/ConsumerDataPage';\nimport { SubscriptionTermsPage } from '@/pages/SubscriptionTermsPage';\nimport { MedicalDirectorPage } from '@/pages/MedicalDirectorPage';\nimport { LabDetailPage, OrderLabsPage } from '@/pages/OrderLabsPage';\nimport { AdminApp } from '@/admin/AdminApp';\nimport { AccountGate } from '@/pages/account/AccountGate';\nimport { AccountLoginPage } from '@/pages/account/AccountLoginPage';\nimport { AccountSignupPage } from '@/pages/account/AccountSignupPage';\nimport { AccountAuthCallbackPage } from '@/pages/account/AccountAuthCallbackPage';\nimport { AccountResetPasswordPage } from '@/pages/account/AccountResetPasswordPage';\nimport { AccountOverviewPage } from '@/pages/account/AccountOverviewPage';\nimport { AccountProfilePage } from '@/pages/account/AccountProfilePage';\nimport { AccountComingSoonPage } from '@/pages/account/AccountComingSoonPage';\nimport { AccountOrdersPage } from '@/pages/account/AccountOrdersPage';\nimport { AccountOrderDetailPage } from '@/pages/account/AccountOrderDetailPage';\nimport { CherryFinancingWidget } from '@/components/CherryFinancingWidget';\nimport { WelcomePopup } from '@/components/WelcomePopup';\nimport { FeelingPopup } from '@/components/FeelingPopup';\nimport { CareCheckoutReturn } from '@/components/CareCheckoutReturn';\n\nfunction App() {\n  const route = useRouter();\n  const { path } = route;\n\n  // Redirect legacy hash URLs to clean path URLs on initial load\n  useEffect(() => {\n    if (window.location.hash && window.location.hash.startsWith('#/')) {\n      const cleanPath = window.location.hash.slice(1);\n      window.history.replaceState({}, '', cleanPath);\n      window.dispatchEvent(new PopStateEvent('popstate'));\n    }\n  }, []);\n\n  // Legacy /shop alias → canonical /shop-all\n  useEffect(() => {\n    if (path === '/shop') {\n      window.history.replaceState({}, '', '/shop-all');\n      window.dispatchEvent(new PopStateEvent('popstate'));\n    }\n  }, [path]);\n\n  // Admin area renders with its own chrome (no storefront header/footer/cart).\n  if (path === '/admin' || path.startsWith('/admin/')) {\n    return <AdminApp route={route} />;\n  }\n\n  const renderPage = () => {\n    if (path === '/' || path === '') return <HomePage />;\n    if (path === '/goals') return <GoalsPage />;\n    if (path.startsWith('/goal/')) return <GoalPage goalId={path.replace('/goal/', '')} />;\n    if (path.startsWith('/concern/')) return <ConcernPage concernId={path.replace('/concern/', '')} />;\n    if (path.startsWith('/section/')) return <SectionPage sectionId={path.replace('/section/', '')} subFilter={route.query.sub} />;\n    if (path === '/best-sellers') return <BestSellersPage />;\n    if (path.startsWith('/product/')) return <ProductPage slug={path.replace('/product/', '')} />;\n    if (path === '/checkout') return <CheckoutPage />;\n    if (path === '/groupon') return <GrouponPage />;\n    if (path.startsWith('/order/payment/')) {\n      const orderNumber = path.replace('/order/payment/', '').split('/')[0];\n      return <OrderPaymentInstructionsPage publicOrderNumber={orderNumber} />;\n    }\n    if (path.startsWith('/order/card-result/')) {\n      return <KashuCardResultPage />;\n    }\n    if (path === '/success') return <SuccessPage />;\n    if (path === '/cancel') return <CancelPage />;\n\n    if (path === '/account/login') {\n      return (\n        <AccountGate publicOnly>\n          <AccountLoginPage />\n        </AccountGate>\n      );\n    }\n    if (path === '/account/signup') {\n      return (\n        <AccountGate publicOnly>\n          <AccountSignupPage />\n        </AccountGate>\n      );\n    }\n    if (path === '/account/auth/callback') {\n      return (\n        <AccountGate publicOnly>\n          <AccountAuthCallbackPage />\n        </AccountGate>\n      );\n    }\n    if (path === '/account/reset-password') {\n      return (\n        <AccountGate publicOnly>\n          <AccountResetPasswordPage />\n        </AccountGate>\n      );\n    }\n    if (path === '/account') {\n      return (\n        <AccountGate>\n          <AccountOverviewPage />\n        </AccountGate>\n      );\n    }\n    if (path === '/account/profile') {\n      return (\n        <AccountGate>\n          <AccountProfilePage />\n        </AccountGate>\n      );\n    }\n    if (path === '/account/orders') {\n      return (\n        <AccountGate>\n          <AccountOrdersPage />\n        </AccountGate>\n      );\n    }\n    if (path.startsWith('/account/orders/')) {\n      const orderId = path.replace('/account/orders/', '').split('/')[0];\n      return (\n        <AccountGate>\n          <AccountOrderDetailPage orderId={orderId} />\n        </AccountGate>\n      );\n    }\n    if (path === '/account/subscriptions' || path === '/account/membership' || path === '/account/auto-refill') {\n      return (\n        <AccountGate>\n          <AccountComingSoonPage\n            active=\"membership\"\n            title=\"Subscriptions\"\n            description=\"Prescription renewals and subscription-related care steps are handled securely in GEN Health.\"\n          />\n        </AccountGate>\n      );\n    }\n    if (path === '/account/requests') {\n      return (\n        <AccountGate>\n          <AccountComingSoonPage\n            active=\"requests\"\n            title=\"Requests\"\n            description=\"Prescription requests, refill questions, follow-ups, and lab review steps continue in GEN Health.\"\n          />\n        </AccountGate>\n      );\n    }\n\n    if (path === '/track') return <TrackPage />;\n    if (path === '/about') return <AboutPage />;\n    if (path === '/medical-director') return <MedicalDirectorPage />;\n    if (path.startsWith('/order-labs/')) return <LabDetailPage slug={path.replace('/order-labs/', '').split('/')[0]} />;\n    if (path === '/order-labs') return <OrderLabsPage />;\n    if (path === '/faq') return <FaqPage />;\n    if (path === '/memberships' || path === '/subscriptions') return <SubscriptionsPage />;\n    if (path === '/alacarte') return <AlaCartePage />;\n    if (path === '/refund-policy') return <RefundPolicyPage />;\n    if (path === '/shipping-policy') return <ShippingPolicyPage />;\n    if (path === '/membership-terms' || path === '/subscription-terms') return <SubscriptionTermsPage />;\n    if (path === '/accessibility') return <AccessibilityPage />;\n    if (path === '/consumer-data') return <ConsumerDataPage />;\n    if (path === '/contact') return <ContactPage />;\n    if (path === '/shop' || path === '/shop-all') return <ShopAllPage />;\n    if (path === '/privacy-policy') return <PrivacyPolicyPage />;\n    if (path === '/terms') return <TermsPage />;\n\n    return (\n      <div className=\"pt-32 pb-20 text-center\">\n        <p className=\"font-serif text-3xl text-ink-900 mb-3\">Page not found</p>\n        <p className=\"text-ink-500 mb-6\">The page you are looking for does not exist.</p>\n        <a href=\"/\" className=\"btn-primary\">Back to Home</a>\n      </div>\n    );\n  };\n\n  return (\n    <CustomerAuthProvider>\n      <MemberProvider>\n        <PrescriptionBasketProvider>\n          <CartProvider>\n            <div className=\"min-h-screen bg-cream-50\">\n              <Header />\n              <main>{renderPage()}</main>\n              <Footer />\n              <CartDrawer />\n              <PrescriptionBasketDrawer />\n              <CareCheckoutReturn />\n              <WelcomePopup />\n              <FeelingPopup />\n              {/* Financing discovery only — does not replace Tagada card checkout */}\n              <CherryFinancingWidget />\n            </div>\n          </CartProvider>\n        </PrescriptionBasketProvider>\n      </MemberProvider>\n    </CustomerAuthProvider>\n  );\n}\n\nexport default App;\n"},{"file":"src/components/GenHostedProductPage.tsx","before":"1358e42ee7f270c37283a5bb32be768d946b4e6d209273390dbb76eb57f29fe1","next":"import { useMemo, useState } from 'react';\nimport { ChevronLeft, ChevronRight, ShieldCheck, X } from 'lucide-react';\nimport { Link } from '@/router';\nimport { usePrescriptionBasket } from '@/context/PrescriptionBasketContext';\nimport { getRelatedProducts, type Product } from '@/data/products';\nimport { navigateToGenProductFirstCheckout, resolveGenProductFirstCheckout } from '@/lib/commerce/genHostedCheckout';\nimport { GEN_HOSTED_PRODUCTS, type GenHostedProductOption } from '@/lib/commerce/genHostedProducts';\nimport { ProductDescriptionSections, ProductHighlights } from '@/components/ProductDescriptionSections';\n\nexport function GenHostedProductPage({ product, route }: { product: Product; route: (typeof GEN_HOSTED_PRODUCTS)[string] }) {\n  const options: readonly GenHostedProductOption[] = route.options ?? [{\n    label: product.dosageForms[0] || 'Prescription option',\n    price: route.price,\n    genClientProductId: route.genClientProductId,\n  }];\n  const [selectedOptionIndex, setSelectedOptionIndex] = useState(0);\n  const selectedOption = options[selectedOptionIndex] ?? options[0];\n  const checkout = resolveGenProductFirstCheckout(selectedOption.genClientProductId);\n  const { addItem, openBasket, items: prescriptionItems } = usePrescriptionBasket();\n  const [recommendationsOpen, setRecommendationsOpen] = useState(false);\n  const [recommendationOffset, setRecommendationOffset] = useState(0);\n  const currentInBasket = prescriptionItems.some(item => item.slug === product.slug && item.genClientProductId === selectedOption.genClientProductId);\n  const recommendations = useMemo(\n    () =>\n      getRelatedProducts(product, 8)\n        .filter(candidate => candidate.category !== 'accessories' && candidate.category !== 'provider-care')\n        .filter(candidate => {\n          const candidateRoute = GEN_HOSTED_PRODUCTS[candidate.slug];\n          return Boolean(candidateRoute && resolveGenProductFirstCheckout(candidateRoute.genClientProductId).ok);\n        })\n        .slice(0, 3),\n    [product],\n  );\n  const orderedRecommendations = recommendations.length\n    ? recommendations.map((_, index) => recommendations[(index + recommendationOffset) % recommendations.length])\n    : [];\n\n  const openRecommendations = () => {\n    setRecommendationOffset(0);\n    setRecommendationsOpen(true);\n  };\n\n  const addCurrentToBasket = () => {\n    if (!checkout.ok) return;\n    addItem({\n      slug: product.slug,\n      displayName: options.length > 1 ? `${product.shortName} — ${selectedOption.label}` : product.displayName,\n      subtitle: options.length > 1 ? selectedOption.label : product.subtitle,\n      image: product.image,\n      imageAlt: product.imageAlt,\n      price: selectedOption.price,\n      genClientProductId: selectedOption.genClientProductId,\n      category: product.category,\n    });\n    openBasket();\n  };\n\n  const continueToGen = () => {\n    if (checkout.ok) navigateToGenProductFirstCheckout(checkout.url);\n  };\n\n  return (\n    <div className=\"bg-cream-50 pt-28 md:pt-32 pb-16\">\n      <div className=\"container-lux grid gap-8 lg:grid-cols-2 lg:gap-16\">\n        <img src={product.image} alt={product.imageAlt} className=\"aspect-square w-full rounded-3xl object-cover\" />\n        <div>\n          <p className=\"flex items-center gap-1.5 text-xs uppercase tracking-wider-2 text-gold-600\"><ShieldCheck size={16} />Provider review required</p>\n          <h1 className=\"mt-3 font-serif text-4xl text-ink-900\">{product.displayName}</h1>\n          <p className=\"mt-3 text-xl text-ink-700 leading-snug\">{product.benefitHeadline}</p>\n          <p className=\"mt-4 text-ink-600 leading-relaxed\">{product.shortDescription}</p>\n          <ProductHighlights highlights={product.highlights} />\n          {options.length > 1 && (\n            <div className=\"mt-6\">\n              <p className=\"mb-2 text-sm font-medium text-ink-900\">Delivery method</p>\n              <div className=\"flex flex-wrap gap-2\" role=\"group\" aria-label=\"Delivery method\">\n                {options.map((option, index) => (\n                  <button\n                    key={option.label}\n                    type=\"button\"\n                    onClick={() => setSelectedOptionIndex(index)}\n                    aria-pressed={index === selectedOptionIndex}\n                    className={index === selectedOptionIndex ? 'rounded-full bg-ink-900 px-4 py-2 text-sm text-white' : 'rounded-full border border-cream-300 bg-white px-4 py-2 text-sm text-ink-700'}\n                  >\n                    {option.label} · ${option.price}\n                  </button>\n                ))}\n              </div>\n            </div>\n          )}\n          <div className=\"mt-6 rounded-2xl border border-cream-300 bg-white p-5\">\n            <p className=\"text-sm text-ink-500\">Estimated prescription total</p>\n            <p className=\"font-serif text-3xl text-ink-900\">${selectedOption.price.toFixed(2)}</p>\n            <p className=\"mt-2 text-xs text-ink-500\">Complete your intake in GEN Health before product payment. Provider review is required before dispensing.</p>\n            {checkout.ok ? (\n              <a href={checkout.url} target=\"_blank\" rel=\"noopener noreferrer\" onClick={event => { if (!event.ctrlKey && !event.metaKey && !event.shiftKey && !event.altKey) { event.preventDefault(); continueToGen(); } }} className=\"btn-primary mt-5 w-full\">Buy now</a>\n            ) : (\n              <button type=\"button\" className=\"btn-primary mt-5 w-full\" disabled>Temporarily unavailable</button>\n            )}\n            {checkout.ok && <button type=\"button\" className=\"btn-outline mt-2 w-full\" onClick={addCurrentToBasket}>{currentInBasket ? 'Review prescription basket' : 'Save to Care Basket'}</button>}\n            {currentInBasket && <button type=\"button\" onClick={openBasket} className=\"btn-ghost mt-2 w-full\">Open prescription basket</button>}\n            <p className=\"mt-3 text-xs text-ink-500\">Each prescription is purchased separately. Payment does not guarantee prescription approval.</p>\n          </div>\n        </div>\n      </div>\n      <div className=\"container-lux -mt-8 pb-16 lg:-mt-16\">\n        <div className=\"lg:ml-[calc(50%+2rem)] lg:w-[calc(50%-2rem)] border-t border-cream-300 pt-8\">\n          <ProductDescriptionSections product={product} />\n        </div>\n      </div>\n\n      {recommendationsOpen && (\n        <div\n          className=\"fixed inset-0 z-[70] flex items-center justify-center bg-ink-950/45 px-5 py-8 backdrop-blur-sm animate-fade-in\"\n          onClick={() => setRecommendationsOpen(false)}\n        >\n          <div\n            className=\"max-h-[90vh] w-full max-w-5xl overflow-y-auto rounded-3xl border border-cream-300 bg-cream-50 p-5 shadow-2xl animate-scale-in md:p-7\"\n            role=\"dialog\"\n            aria-modal=\"true\"\n            aria-labelledby=\"commonly-purchased-title\"\n            onClick={event => event.stopPropagation()}\n          >\n            <div className=\"flex items-start justify-between gap-4\">\n              <div>\n                <p className=\"text-[10px] font-semibold uppercase tracking-wider-2 text-gold-600\">Before you continue</p>\n                <h2 id=\"commonly-purchased-title\" className=\"mt-1 font-serif text-2xl text-ink-900 md:text-3xl\">Commonly purchased with...</h2>\n                <p className=\"mt-2 max-w-2xl text-sm leading-relaxed text-ink-600\">Explore other provider-reviewed options before checkout. Each prescription is purchased separately through GEN Health and requires its own eligibility review.</p>\n              </div>\n              <button type=\"button\" onClick={() => setRecommendationsOpen(false)} aria-label=\"Close recommendations\" className=\"p-1\">\n                <X size={22} className=\"text-ink-500 hover:text-ink-900\" />\n              </button>\n            </div>\n\n            {orderedRecommendations.length > 0 && (\n              <div className=\"relative mt-6\">\n                <div className=\"grid gap-4 sm:grid-cols-3\">\n                  {orderedRecommendations.map(candidate => {\n                    const candidateRoute = GEN_HOSTED_PRODUCTS[candidate.slug];\n                    if (!candidateRoute) return null;\n                    return (\n                      <Link\n                        key={candidate.slug}\n                        to={`/product/${candidate.slug}`}\n                        onClick={() => setRecommendationsOpen(false)}\n                        className=\"group overflow-hidden rounded-2xl border border-cream-300 bg-white transition-shadow hover:shadow-lg\"\n                      >\n                        <img src={candidate.image} alt={candidate.imageAlt} className=\"aspect-[4/3] w-full object-cover\" />\n                        <div className=\"p-4\">\n                          <p className=\"text-[10px] uppercase tracking-wider text-gold-600\">{candidate.subtitle}</p>\n                          <h3 className=\"mt-1 font-serif text-xl leading-tight text-ink-900 group-hover:text-gold-700\">{candidate.displayName}</h3>\n                          <p className=\"mt-2 text-sm text-ink-500\">Starting at ${candidateRoute.price.toFixed(2)}</p>\n                          <p className=\"mt-3 text-xs font-medium text-gold-700\">View details <span aria-hidden=\"true\">→</span></p>\n                        </div>\n                      </Link>\n                    );\n                  })}\n                </div>\n                {recommendations.length > 1 && (\n                  <div className=\"mt-4 flex items-center justify-center gap-3\">\n                    <button\n                      type=\"button\"\n                      onClick={() => setRecommendationOffset(offset => (offset - 1 + recommendations.length) % recommendations.length)}\n                      aria-label=\"Previous recommendations\"\n                      className=\"rounded-full border border-cream-300 bg-white p-2 text-ink-700 hover:border-gold-400 hover:text-gold-700\"\n                    >\n                      <ChevronLeft size={18} />\n                    </button>\n                    <span className=\"text-xs text-ink-400\">{recommendations.length} prescription options</span>\n                    <button\n                      type=\"button\"\n                      onClick={() => setRecommendationOffset(offset => (offset + 1) % recommendations.length)}\n                      aria-label=\"Next recommendations\"\n                      className=\"rounded-full border border-cream-300 bg-white p-2 text-ink-700 hover:border-gold-400 hover:text-gold-700\"\n                    >\n                      <ChevronRight size={18} />\n                    </button>\n                  </div>\n                )}\n              </div>\n            )}\n\n            <div className=\"mt-7 flex flex-col-reverse gap-2 border-t border-cream-300 pt-5 sm:flex-row sm:justify-end\">\n              <button type=\"button\" onClick={() => setRecommendationsOpen(false)} className=\"btn-ghost w-full sm:w-auto\">Keep shopping</button>\n              <button type=\"button\" onClick={() => { setRecommendationsOpen(false); openBasket(); }} className=\"btn-ghost w-full sm:w-auto\">Review prescription basket</button>\n              <button type=\"button\" onClick={continueToGen} className=\"btn-primary w-full sm:w-auto\">Continue with this prescription</button>\n            </div>\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n"},{"file":"src/components/PrescriptionBasketDrawer.tsx","before":"81b4f1d6b23f3c8d1b1d5e31fe203ce7a98f4b15c655e2a75b074b98ceccb6c5","next":"import { useState } from 'react';\nimport { GrouponEntry } from '@/components/GrouponEntry';\nimport { ArrowRight, CheckCircle2, ExternalLink, ShieldCheck, ShoppingBag, X } from 'lucide-react';\nimport { navigate } from '@/router';\nimport { usePrescriptionBasket } from '@/context/PrescriptionBasketContext';\nimport { navigateToGenProductFirstCheckout, resolveGenProductFirstCheckout } from '@/lib/commerce/genHostedCheckout';\n\nconst HRT_CATEGORY = 'womens-hormone-therapy';\nconst INITIAL_VISIT_CENTS = 7500;\n\nconst money = (cents: number) => `$${(cents / 100).toFixed(2)}`;\n\nexport function PrescriptionBasketDrawer() {\n  const { items, isOpen, itemCount, medicationSubtotal, closeBasket, removeItem } = usePrescriptionBasket();\n  const [selectedSlug, setSelectedSlug] = useState<string | null>(null);\n  const hasHrt = items.some(item => item.category === HRT_CATEGORY);\n  const hasLabItems = items.some(item => item.category === 'labs');\n  const hasPrescriptionItems = items.some(item => item.category !== 'labs');\n  const selectedItem = items.find(item => item.slug === selectedSlug) ?? items[0] ?? null;\n  const selectedItemAvailable = selectedItem\n    ? Boolean(selectedItem.checkoutUrl) || resolveGenProductFirstCheckout(selectedItem.genClientProductId).ok\n    : false;\n  const estimatedTotalCents =\n    Math.round(medicationSubtotal * 100) +\n    (hasPrescriptionItems ? INITIAL_VISIT_CENTS : 0);\n\n  const beginGenCheckout = (item: NonNullable<typeof selectedItem>) => {\n    if (item.checkoutUrl) {\n      navigateToGenProductFirstCheckout(item.checkoutUrl);\n      return;\n    }\n    const checkout = resolveGenProductFirstCheckout(item.genClientProductId);\n    if (checkout.ok) navigateToGenProductFirstCheckout(checkout.url);\n  };\n\n  if (!isOpen) return null;\n\n  return (\n    <div className=\"fixed inset-0 z-[75]\">\n      <div className=\"absolute inset-0 bg-ink-950/45 backdrop-blur-sm animate-fade-in\" onClick={closeBasket} />\n      <aside className=\"absolute right-0 top-0 flex h-full w-full max-w-xl flex-col bg-cream-50 shadow-2xl animate-slide-in\" aria-label=\"Care basket\">\n        <div className=\"flex items-center justify-between border-b border-cream-300 px-5 py-4\">\n          <div className=\"flex items-center gap-2\">\n            <ShoppingBag size={21} className=\"text-ink-800\" />\n            <span className=\"font-serif text-lg font-medium\">Care Basket</span>\n            <span className=\"text-sm text-ink-400\">({itemCount})</span>\n          </div>\n          <button type=\"button\" onClick={closeBasket} aria-label=\"Close care basket\"><X size={22} className=\"text-ink-500 hover:text-ink-900\" /></button>\n        </div>\n\n        <div className=\"mx-5 mt-4 rounded-xl border border-gold-200 bg-gold-50 px-4 py-3\">\n          <p className=\"text-xs font-semibold text-gold-800\">Care items and accessories stay in separate carts.</p>\n          <p className=\"mt-1 text-xs leading-relaxed text-ink-600\">\n            Prescriptions, labs, and provider visits continue through GEN Health one care item at a time. Accessories stay in the storefront cart with the separate $10 accessory shipping charge.\n          </p>\n        </div>\n\n        {items.length === 0 ? (\n          <div className=\"flex flex-1 flex-col items-center justify-center px-8 text-center\">\n            <div className=\"mb-4 rounded-full bg-cream-200 p-6\"><ShoppingBag size={32} className=\"text-ink-400\" /></div>\n            <p className=\"font-serif text-xl text-ink-900\">Your care basket is empty</p>\n            <p className=\"mt-2 max-w-sm text-sm leading-relaxed text-ink-500\">Add prescription or lab options here before starting secure GEN Health checkout.</p>\n            <button type=\"button\" onClick={() => { closeBasket(); navigate('/shop-all'); }} className=\"btn-primary mt-6\">Browse prescriptions <ArrowRight size={16} /></button>\n          </div>\n        ) : (\n          <>\n            <div className=\"min-h-0 flex-1 overflow-y-auto px-5 py-5\">\n              <div className=\"mb-4 rounded-2xl border border-gold-200 bg-white p-4\">\n                <p className=\"text-xs font-semibold uppercase tracking-wider text-gold-700\">GEN Health checkout steps</p>\n                <p className=\"mt-1 text-sm leading-relaxed text-ink-600\">\n                  Begin prescription intake before payment in GEN Health. Each care item continues separately; your other selections stay saved here.\n                </p>\n                <div className=\"mt-3 space-y-2\">\n                  {items.map((item, index) => {\n                    const available = Boolean(item.checkoutUrl) || resolveGenProductFirstCheckout(item.genClientProductId).ok;\n                    const selected = selectedItem?.slug === item.slug;\n                    return (\n                      <button\n                        key={`step-${item.slug}`}\n                        type=\"button\"\n                        onClick={() => setSelectedSlug(item.slug)}\n                        aria-pressed={selected}\n                        className={`flex w-full items-center gap-3 rounded-xl border px-3 py-3 text-left transition-colors ${\n                          selected ? 'border-gold-400 bg-gold-50 shadow-sm' : 'border-cream-300 bg-cream-50 hover:border-gold-200'\n                        }`}\n                      >\n                        <span className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-xs font-semibold ${\n                          selected ? 'bg-gold-500 text-white' : 'bg-white text-ink-600'\n                        }`}>\n                          {index + 1}\n                        </span>\n                        <span className=\"min-w-0 flex-1\">\n                          <span className=\"block truncate text-sm font-medium text-ink-900\">{item.displayName}</span>\n                          <span className=\"block text-xs text-ink-500\">{item.category === 'labs' ? 'Lab payment in GEN' : 'Prescription review in GEN'}</span>\n                        </span>\n                        <span className={`rounded-full px-2 py-1 text-[10px] font-semibold uppercase tracking-wider ${\n                          available ? 'bg-emerald-50 text-emerald-700' : 'bg-cream-200 text-ink-500'\n                        }`}>\n                          {available ? 'Ready' : 'Unavailable'}\n                        </span>\n                      </button>\n                    );\n                  })}\n                </div>\n              </div>\n\n              <div className=\"space-y-3\">\n                {items.map(item => {\n                  const available = Boolean(item.checkoutUrl) || resolveGenProductFirstCheckout(item.genClientProductId).ok;\n                  return (\n                    <div\n                      key={item.slug}\n                      className={`rounded-2xl border bg-white p-3 transition-colors ${\n                        selectedItem?.slug === item.slug ? 'border-gold-400 ring-1 ring-gold-300' : 'border-cream-300'\n                      }`}\n                    >\n                      <div className=\"flex gap-3\">\n                        <img src={item.image} alt={item.imageAlt} className=\"h-20 w-20 rounded-xl bg-cream-100 object-cover\" />\n                        <div className=\"min-w-0 flex-1\">\n                          <div className=\"flex items-start justify-between gap-2\">\n                            <div>\n                              <p className=\"text-[10px] uppercase tracking-wider text-gold-600\">{item.subtitle}</p>\n                              <h3 className=\"font-serif text-lg leading-tight text-ink-900\">{item.displayName}</h3>\n                            </div>\n                            <div className=\"flex items-center gap-1\">\n                              <label className=\"flex items-center gap-1.5 text-[11px] text-ink-500\">\n                                <input\n                                  type=\"radio\"\n                                  name=\"selected-prescription\"\n                                  checked={selectedItem?.slug === item.slug}\n                                  onChange={() => setSelectedSlug(item.slug)}\n                                  aria-label={`Select ${item.displayName} for GEN checkout`}\n                                  className=\"accent-gold-500\"\n                                />\n                                Select\n                              </label>\n                              <button type=\"button\" onClick={() => removeItem(item.slug)} aria-label={`Remove ${item.displayName}`} className=\"p-1 text-ink-400 hover:text-ink-900\"><X size={16} /></button>\n                            </div>\n                          </div>\n                          <p className=\"mt-1 text-sm font-medium text-ink-900\">{money(Math.round(item.price * 100))}</p>\n                          <p className=\"mt-1 flex items-center gap-1 text-[11px] text-ink-500\"><ShieldCheck size={12} className=\"text-gold-600\" /> {item.category === 'labs' ? 'Opens as its own GEN lab checkout' : 'Opens as its own GEN prescription checkout'}</p>\n                        </div>\n                      </div>\n                      {!available && <p className=\"mt-3 rounded-lg bg-cream-100 px-3 py-2 text-xs text-ink-600\">Temporarily unavailable for secure GEN checkout.</p>}\n                    </div>\n                  );\n                })}\n              </div>\n\n              <div className=\"mt-6 rounded-2xl border border-cream-300 bg-white p-4\">\n                <div className=\"flex items-center justify-between gap-3\">\n                  <div>\n                    <p className=\"text-sm font-medium text-ink-900\">Hormone therapy labs</p>\n                    <p className=\"mt-1 text-xs leading-relaxed text-ink-500\">Only applies when a Women’s Hormone Therapy product is selected.</p>\n                  </div>\n                </div>\n                {hasHrt && (\n                  <div className=\"mt-3 rounded-xl border border-gold-200 bg-gold-50 px-3 py-3\">\n                    <p className=\"text-sm font-medium text-ink-900\">Choose a lab option</p>\n                    <p className=\"mt-1 text-xs leading-relaxed text-ink-600\">\n                      If labs are required, select the in-home or walk-in lab option that fits you and add it to this Care Basket before completing the hormone therapy purchase.\n                    </p>\n                    <button\n                      type=\"button\"\n                      onClick={() => { closeBasket(); navigate('/order-labs'); }}\n                      className=\"mt-3 inline-flex items-center gap-1 text-xs font-medium text-gold-800 underline\"\n                    >\n                      View lab options <ArrowRight size={13} />\n                    </button>\n                  </div>\n                )}\n                <p className=\"mt-3 text-xs leading-relaxed text-ink-500\">\n                  {hasHrt\n                    ? hasLabItems\n                      ? 'Selected lab options are included in the care selections estimate above.'\n                      : 'No lab has been added yet.'\n                    : 'No hormone therapy labs are needed for the current selections.'}\n                </p>\n              </div>\n\n              {hasHrt && <GrouponEntry onOpen={closeBasket} />}\n              <div className=\"mt-4 rounded-2xl border border-gold-200 bg-gold-50 p-4\">\n                <p className=\"text-xs font-semibold uppercase tracking-wider text-gold-800\">Care estimate</p>\n                <div className=\"mt-3 space-y-2 text-sm\">\n                  <div className=\"flex justify-between gap-3\"><span className=\"text-ink-600\">Care selections</span><span className=\"font-medium text-ink-900\">{money(Math.round(medicationSubtotal * 100))}</span></div>\n                  {hasPrescriptionItems && <div className=\"flex justify-between gap-3\"><span className=\"text-ink-600\">Initial provider visit, if required</span><span className=\"font-medium text-ink-900\">{money(INITIAL_VISIT_CENTS)}</span></div>}\n                  {hasHrt && <div className=\"flex justify-between gap-3\"><span className=\"text-ink-600\">Hormone therapy labs, if required</span><span className=\"font-medium text-ink-900\">{hasLabItems ? 'Included above' : 'Choose option'}</span></div>}\n                  {hasPrescriptionItems && <div className=\"flex justify-between gap-3\"><span className=\"text-ink-600\">Care item shipping</span><span className=\"font-medium text-ink-900\">Included when available</span></div>}\n                  <div className=\"flex justify-between gap-3 border-t border-gold-200 pt-2\"><span className=\"font-medium text-ink-900\">Estimated care total</span><span className=\"font-medium text-ink-900\">{money(estimatedTotalCents)}</span></div>\n                </div>\n                <p className=\"mt-3 text-[11px] leading-relaxed text-gold-900\">GEN Health confirms the final amount, any required visits or labs, and shipping availability for each item. Provider review is required; a prescription is not guaranteed. Accessories are not included here.</p>\n              </div>\n\n              <div className=\"mt-4 rounded-2xl border border-cream-300 bg-white p-4\">\n                <div className=\"flex gap-3\">\n                  <CheckCircle2 size={20} className=\"mt-0.5 shrink-0 text-gold-600\" />\n                  <div>\n                    <p className=\"text-sm font-medium text-ink-900\">Storefront cart stays separate</p>\n                    <p className=\"mt-1 text-xs leading-relaxed text-ink-500\">\n                      Accessories use the regular cart icon and checkout on My Bare Method. That is the only place the $10 accessory shipping charge appears.\n                    </p>\n                  </div>\n                </div>\n              </div>\n            </div>\n\n            <div className=\"shrink-0 border-t border-cream-300 px-5 py-4\">\n              <p className=\"mb-3 text-xs leading-relaxed text-ink-500\">Start with the selected care item below. Prescriptions begin with intake; labs use their separate lab checkout. External payments require staff verification.</p>\n              {selectedItem && (\n                <div className=\"mb-3 rounded-xl border border-gold-200 bg-gold-50 p-3\">\n                  <p className=\"text-xs text-gold-900\">Selected GEN checkout: <span className=\"font-semibold\">{selectedItem.displayName}</span></p>\n                  <button\n                    type=\"button\"\n                    onClick={() => beginGenCheckout(selectedItem)}\n                    disabled={!selectedItemAvailable}\n                    className=\"btn-primary mt-2 w-full text-sm\"\n                  >\n                    {selectedItemAvailable ? <>{selectedItem.category === 'labs' ? 'Continue to Lab Checkout' : 'Begin Intake in GEN'} <ExternalLink size={14} /></> : 'Temporarily unavailable'}\n                  </button>\n                </div>\n              )}\n              <button type=\"button\" onClick={closeBasket} className=\"btn-ghost w-full\">Keep shopping</button>\n            </div>\n          </>\n        )}\n      </aside>\n    </div>\n  );\n}\n"},{"file":"src/lib/commerce/genHostedCheckout.ts","before":"541a673679c4345c29535795fd0a6a8332b6a5501e91dd8af8b0a2306b89b03a","next":"import { isOwnerVerifiedGenClientProductId } from '@/data/websiteFamilies';\nimport { openCareCheckoutWindow } from './careCheckoutWindow';\n\nconst GEN_APP_ORIGIN = 'https://app.genhealthehr.com';\nconst MBM_GEN_CLIENT_ID = 'f5e0mdyBYnDh7HGvek0C';\nconst MBM_GEN_PRODUCT_PREFIX = `${MBM_GEN_CLIENT_ID}_MoDyAcICE5RDa4DfaeBX_`;\n\n/** Recurring GEN checkout has not yet been production-verified for MBM. */\nexport const GEN_RECURRING_CHECKOUT_ENABLED = false;\n\nexport type GenHostedCheckoutResolution =\n  | { ok: true; url: string }\n  | {\n      ok: false;\n      code: 'MISSING_PRODUCT_ID' | 'WRONG_CLIENT' | 'PAIRING_NOT_VERIFIED';\n    };\n\n/**\n * Resolve an owner-verified GEN product to intake before product payment.\n * The legacy function name is retained for existing catalog callers.\n * This remains a single-product flow, not a combined cart or shared intake.\n */\nexport function resolveGenProductFirstCheckout(\n  genClientProductId: string | null | undefined,\n): GenHostedCheckoutResolution {\n  const id = (genClientProductId || '').trim();\n  if (!id) return { ok: false, code: 'MISSING_PRODUCT_ID' };\n  if (!id.startsWith(MBM_GEN_PRODUCT_PREFIX)) {\n    return { ok: false, code: 'WRONG_CLIENT' };\n  }\n  if (!isOwnerVerifiedGenClientProductId(id)) {\n    return { ok: false, code: 'PAIRING_NOT_VERIFIED' };\n  }\n\n  return {\n    ok: true,\n    url: `${GEN_APP_ORIGIN}/${MBM_GEN_CLIENT_ID}/product/${encodeURIComponent(id)}?checkoutFlow=intake_first`,\n  };\n}\n\n/** Keep MBM open while the customer completes hosted checkout. */\nexport function navigateToGenProductFirstCheckout(url: string): void {\n  openCareCheckoutWindow(url);\n}\n"},{"file":"src/pages/FamilyProductPage.tsx","before":"19b2cb624a634f8cb2ffd444a5238b67cb0c9c4178d5b470ffd14c5be3370967","next":"import { useMemo, useState } from 'react';\nimport { ChevronLeft, ChevronRight, ShieldCheck, X } from 'lucide-react';\nimport { Link } from '@/router';\nimport { usePrescriptionBasket } from '@/context/PrescriptionBasketContext';\nimport {\n  getRelatedProducts,\n  sections,\n  type Product,\n} from '@/data/products';\nimport { ProductCard } from '@/components/ProductCard';\nimport { ProductDescriptionSections, ProductHighlights } from '@/components/ProductDescriptionSections';\nimport {\n  getWebsiteFamilyBySlug,\n  listPatientVisibleVariants,\n  lockedRetailPrice,\n  resolveFamilyVariant,\n  WEBSITE_FAMILY_CUTOVER_ENABLED,\n  type FamilySelectorState,\n  type WebsiteProductFamily,\n} from '@/data/websiteFamilies';\nimport {\n  navigateToGenProductFirstCheckout,\n  resolveGenProductFirstCheckout,\n} from '@/lib/commerce/genHostedCheckout';\nimport { GEN_HOSTED_PRODUCTS } from '@/lib/commerce/genHostedProducts';\n\nconst LIVE_GLP1_PROGRAMS = {\n  semaglutide: {\n    low: { label: 'Low Dose', price: 139, id: 'f5e0mdyBYnDh7HGvek0C_MoDyAcICE5RDa4DfaeBX_7UMqZumyeXaWMX9zOPP3' },\n    high: { label: 'High Dose', price: 149, id: 'f5e0mdyBYnDh7HGvek0C_MoDyAcICE5RDa4DfaeBX_uM0cXePP8e9c5hiMKcRt' },\n    monthly: { label: 'Monthly', price: 129, id: 'f5e0mdyBYnDh7HGvek0C_MoDyAcICE5RDa4DfaeBX_1sgLVERqG9oWU9WKht9b' },\n  },\n  tirzepatide: {\n    low: { label: 'Low Dose', price: 259, id: 'f5e0mdyBYnDh7HGvek0C_MoDyAcICE5RDa4DfaeBX_mhUSqSGlaFVCghW3V3DD' },\n    high: { label: 'High Dose', price: 279, id: 'f5e0mdyBYnDh7HGvek0C_MoDyAcICE5RDa4DfaeBX_43kVbBgNLBocKyVUhQmG' },\n    monthly: { label: 'Monthly', price: 249, id: 'f5e0mdyBYnDh7HGvek0C_MoDyAcICE5RDa4DfaeBX_YkHkffkLKFz3FjC7Wvno' },\n  },\n} as const;\n\ntype Glp1ProgramChoice = 'low' | 'high' | 'monthly';\n\nfunction unique(values: Array<string | null | undefined>): string[] {\n  const out: string[] = [];\n  for (const v of values) {\n    const s = (v || '').trim();\n    if (s && !out.includes(s)) out.push(s);\n  }\n  return out;\n}\n\nfunction formatPrice(amount: number): string {\n  return `$${amount.toFixed(2)}`;\n}\n\nexport function isFamilyStorefrontSlug(slug: string): boolean {\n  if (!WEBSITE_FAMILY_CUTOVER_ENABLED) return false;\n  const family = getWebsiteFamilyBySlug(slug);\n  if (!family) return false;\n  return listPatientVisibleVariants(family).length > 0;\n}\n\nexport function FamilyProductPage({\n  product,\n  initialPurchaseType,\n}: {\n  product: Product;\n  initialPurchaseType?: 'one_time' | 'membership';\n}) {\n  const family = getWebsiteFamilyBySlug(product.slug);\n  const related = getRelatedProducts(product);\n  const section = sections.find((s) => s.id === product.category);\n\n  if (!family) {\n    return (\n      <div className=\"pt-32 pb-20 text-center\">\n        <p className=\"text-ink-500\">Product not found.</p>\n        <Link to=\"/shop-all\" className=\"btn-outline mt-6\">\n          Back to shop\n        </Link>\n      </div>\n    );\n  }\n\n  return (\n    <FamilySelectors\n      product={product}\n      family={family}\n      related={related}\n      sectionLabel={section?.label}\n      initialPurchaseType={initialPurchaseType}\n    />\n  );\n}\n\nfunction FamilySelectors({\n  product,\n  family,\n  related,\n  sectionLabel,\n  initialPurchaseType,\n}: {\n  product: Product;\n  family: WebsiteProductFamily;\n  related: Product[];\n  sectionLabel?: string;\n  initialPurchaseType?: 'one_time' | 'membership';\n}) {\n  const visible = listPatientVisibleVariants(family);\n  const familyId = family.familyId;\n  const isWeight = familyId === 'semaglutide' || familyId === 'tirzepatide';\n  const isNad = familyId === 'nad';\n  const isWolverine = familyId === 'wolverine-bpc-tb';\n\n  const oneTime = visible.filter((v) => v.purchaseType === 'one_time');\n  const additives = unique(oneTime.map((v) => v.additive));\n  const forms = unique(visible.map((v) => v.form));\n  const nasalOptions = unique(\n    visible.filter((v) => (v.form || '').toLowerCase().includes('nasal')).map((v) => v.websiteVariantId),\n  );\n\n  void initialPurchaseType;\n  const [additive] = useState(additives[0] || 'Vitamin B12');\n  const [form, setForm] = useState(forms[0] || '');\n  const [nasalOption, setNasalOption] = useState<'r84' | 'r85'>(\n    nasalOptions.includes('nad-nasal-r85') && !nasalOptions.includes('nad-nasal-r84') ? 'r85' : 'r84',\n  );\n  const [injPackage, setInjPackage] = useState<'5mL' | '10mL'>('5mL');\n  const [glp1Program, setGlp1Program] = useState<Glp1ProgramChoice>('low');\n  const { addItem, openBasket, items: prescriptionItems } = usePrescriptionBasket();\n  const [recommendationsOpen, setRecommendationsOpen] = useState(false);\n  const [recommendationOffset, setRecommendationOffset] = useState(0);\n  const glp1FamilyId = familyId === 'semaglutide' || familyId === 'tirzepatide' ? familyId : null;\n  const liveGlp1Program = glp1FamilyId ? LIVE_GLP1_PROGRAMS[glp1FamilyId][glp1Program] : null;\n\n  const selectors: FamilySelectorState = useMemo(() => {\n    if (isWeight) {\n      return {\n        purchaseType: 'one_time',\n        additive,\n        requestedDose: undefined,\n      };\n    }\n    if (isNad) {\n      return { form, nasalOption, package: injPackage };\n    }\n    if (isWolverine) {\n      return { form };\n    }\n    return {};\n  }, [isWeight, isNad, isWolverine, additive, form, nasalOption, injPackage]);\n\n  const resolution = useMemo(\n    () => resolveFamilyVariant(familyId, selectors),\n    [familyId, selectors],\n  );\n  const variant = resolution.variant;\n  const price = variant ? lockedRetailPrice(variant) : null;\n\n  const injReady = visible.some((v) => v.websiteVariantId.startsWith('nad-inj-'));\n  const nasalReady = visible.some((v) => v.websiteVariantId.startsWith('nad-nasal-'));\n  const r84Ready = visible.some((v) => v.websiteVariantId === 'nad-nasal-r84');\n  const r85Ready = visible.some((v) => v.websiteVariantId === 'nad-nasal-r85');\n\n  const displayPrice = liveGlp1Program?.price ?? price;\n  const fixedShipping = 0;\n  const dueToday = displayPrice == null ? null : displayPrice + fixedShipping;\n  const genCheckout = resolveGenProductFirstCheckout(liveGlp1Program?.id ?? variant?.genClientProductId);\n  const selectedGenClientProductId = liveGlp1Program?.id ?? variant?.genClientProductId;\n  const basketSlug = `${product.slug}:${selectedGenClientProductId || 'unresolved'}`;\n  const currentInBasket = prescriptionItems.some(item => item.slug === basketSlug);\n  const recommendations = useMemo(\n    () =>\n      getRelatedProducts(product, 8)\n        .filter(candidate => candidate.category !== 'accessories' && candidate.category !== 'provider-care')\n        .filter(candidate => {\n          const candidateRoute = GEN_HOSTED_PRODUCTS[candidate.slug];\n          return Boolean(candidateRoute && resolveGenProductFirstCheckout(candidateRoute.genClientProductId).ok);\n        })\n        .slice(0, 3),\n    [product],\n  );\n  const orderedRecommendations = recommendations.length\n    ? recommendations.map((_, index) => recommendations[(index + recommendationOffset) % recommendations.length])\n    : [];\n  const canPurchase = glp1FamilyId\n    ? Boolean(liveGlp1Program && genCheckout.ok)\n    : Boolean(variant && price != null && resolution.ok && genCheckout.ok);\n\n  const addCurrentToBasket = () => {\n    if (!genCheckout.ok || displayPrice == null || !selectedGenClientProductId) return;\n    addItem({\n      slug: basketSlug,\n      displayName: family.displayName,\n      subtitle: liveGlp1Program?.label ?? variant?.displayLabel ?? product.subtitle,\n      image: product.image,\n      imageAlt: product.imageAlt,\n      price: displayPrice,\n      genClientProductId: selectedGenClientProductId,\n      category: product.category,\n    });\n    openBasket();\n  };\n\n  const continueToGen = () => {\n    if (genCheckout.ok) navigateToGenProductFirstCheckout(genCheckout.url);\n  };\n\n  return (\n    <div className=\"bg-cream-50 pt-28 md:pt-32\">\n      <div className=\"container-lux py-4\">\n        <div className=\"flex items-center gap-2 text-sm text-ink-400 flex-wrap\">\n          <Link to=\"/\" className=\"hover:text-ink-900\">\n            Home\n          </Link>\n          <span>/</span>\n          <Link to={`/section/${product.category}`} className=\"hover:text-ink-900\">\n            {sectionLabel}\n          </Link>\n          <span>/</span>\n          <span className=\"text-ink-700\">{family.displayName}</span>\n        </div>\n      </div>\n\n      <section className=\"pb-12 md:pb-16\">\n        <div className=\"container-lux\">\n          <div className=\"grid gap-8 lg:grid-cols-2 lg:gap-16\">\n            <div className=\"lg:sticky lg:top-24 lg:self-start\">\n              <div className=\"relative aspect-square overflow-hidden rounded-3xl bg-cream-100\">\n                <img\n                  src={product.image}\n                  alt={product.imageAlt}\n                  className=\"h-full w-full object-cover\"\n                />\n                <div className=\"absolute left-4 top-4 flex flex-col gap-2\">\n                  {product.bestSeller && (\n                    <span className=\"rounded-full bg-ink-900 px-3 py-1 text-[10px] font-medium uppercase tracking-wider text-cream-50\">\n                      Best Seller\n                    </span>\n                  )}\n                  {product.requiresProviderReview && (\n                    <span className=\"rounded-full bg-cream-50/95 px-3 py-1 text-[10px] font-medium uppercase tracking-wider text-ink-900\">\n                      Provider review required\n                    </span>\n                  )}\n                </div>\n              </div>\n            </div>\n\n            <div>\n              <div className=\"flex items-center gap-2 mb-3\">\n                <span className=\"flex items-center gap-1.5 text-xs uppercase tracking-wider-2 text-gold-600\">\n                  <ShieldCheck size={16} /> {sectionLabel}\n                </span>\n              </div>\n              <h1 className=\"font-serif text-4xl md:text-5xl text-ink-900 mb-2 leading-tight\">\n                {family.displayName}\n              </h1>\n              <p className=\"text-xl md:text-2xl text-ink-700 mb-3 leading-snug\">{product.benefitHeadline}</p>\n              <p className=\"text-ink-600 leading-relaxed mb-5\">{product.shortDescription}</p>\n              <ProductHighlights highlights={product.highlights} />\n\n              <div className=\"mb-6 space-y-5\">\n                {glp1FamilyId && (\n                  <fieldset>\n                    <legend className=\"text-sm font-medium text-ink-900 mb-2\">Program option</legend>\n                    <div className=\"flex flex-wrap gap-2\">\n                      {(Object.keys(LIVE_GLP1_PROGRAMS[glp1FamilyId]) as Glp1ProgramChoice[]).map((choice) => {\n                        const option = LIVE_GLP1_PROGRAMS[glp1FamilyId][choice];\n                        return <SelectorChip key={choice} selected={glp1Program === choice} onClick={() => setGlp1Program(choice)} label={`${option.label} · ${formatPrice(option.price)}${choice === 'monthly' ? '/mo' : ''}`} />;\n                      })}\n                    </div>\n                    <p className=\"mt-2 text-xs text-ink-500 leading-relaxed\">Shipping and provider consultation are included. Your provider determines final clinical eligibility and treatment details.</p>\n                  </fieldset>\n                )}\n\n                {isNad && (\n                  <fieldset>\n                    <legend className=\"text-sm font-medium text-ink-900 mb-2\">Delivery method</legend>\n                    <div className=\"flex flex-wrap gap-2\">\n                      <SelectorChip\n                        selected={form === 'Injection'}\n                        disabled={!injReady}\n                        onClick={() => setForm('Injection')}\n                        label={injReady ? 'Injection' : 'Injection · Temporarily unavailable'}\n                      />\n                      {nasalReady && (\n                        <SelectorChip\n                          selected={form === 'Nasal Spray' || !form}\n                          onClick={() => setForm('Nasal Spray')}\n                          label=\"Nasal Spray\"\n                        />\n                      )}\n                    </div>\n                    <p className=\"mt-2 text-xs text-ink-500 leading-relaxed\">\n                      Select your preferred delivery method. Final formulation and directions are determined after provider review.\n                    </p>\n                  </fieldset>\n                )}\n\n                {isNad && form === 'Injection' && injReady && (\n                  <fieldset>\n                    <legend className=\"text-sm font-medium text-ink-900 mb-2\">Package</legend>\n                    <div className=\"flex flex-wrap gap-2\">\n                      {visible.some((v) => v.websiteVariantId === 'nad-inj-5ml-500') && (\n                        <SelectorChip\n                          selected={injPackage === '5mL'}\n                          onClick={() => setInjPackage('5mL')}\n                          label=\"5 mL vial\"\n                        />\n                      )}\n                      {visible.some((v) => v.websiteVariantId === 'nad-inj-10ml-1000') && (\n                        <SelectorChip\n                          selected={injPackage === '10mL'}\n                          onClick={() => setInjPackage('10mL')}\n                          label=\"10 mL vial\"\n                        />\n                      )}\n                    </div>\n                  </fieldset>\n                )}\n\n                {isNad && form === 'Nasal Spray' && r84Ready && r85Ready && (\n                  <fieldset>\n                    <legend className=\"text-sm font-medium text-ink-900 mb-2\">Nasal option</legend>\n                    <div className=\"flex flex-wrap gap-2\">\n                      {r84Ready && (\n                        <SelectorChip\n                          selected={nasalOption === 'r84'}\n                          onClick={() => setNasalOption('r84')}\n                          label=\"Nasal Spray Option 1\"\n                        />\n                      )}\n                      {r85Ready && (\n                        <SelectorChip\n                          selected={nasalOption === 'r85'}\n                          onClick={() => setNasalOption('r85')}\n                          label=\"Nasal Spray Option 2\"\n                        />\n                      )}\n                    </div>\n                  </fieldset>\n                )}\n\n                {isWolverine && forms.length > 0 && (\n                  <fieldset>\n                    <legend className=\"text-sm font-medium text-ink-900 mb-2\">Form</legend>\n                    <div className=\"flex flex-wrap gap-2\">\n                      {forms.map((opt) => (\n                        <SelectorChip\n                          key={opt}\n                          selected={form === opt}\n                          onClick={() => setForm(opt)}\n                          label={opt}\n                        />\n                      ))}\n                    </div>\n                  </fieldset>\n                )}\n              </div>\n\n              <div className=\"rounded-2xl border border-cream-300 bg-white p-5 mb-6\">\n                <div className=\"flex items-end justify-between gap-4 mb-4\">\n                  <div>\n                    <p className=\"text-sm text-ink-500\">Estimated prescription total</p>\n                    <p className=\"font-serif text-3xl text-ink-900\">\n                      {dueToday != null ? formatPrice(dueToday) : '—'}\n                    </p>\n                    <p className=\"mt-1 text-xs text-ink-500\">\n                      {liveGlp1Program\n                        ? `${glp1Program === 'monthly' ? 'Monthly price' : 'One-time price'} shown. Shipping and provider consultation are included.`\n                        : fixedShipping > 0\n                        ? `Includes ${formatPrice(fixedShipping)} shipping. Any applicable visit charge is shown before payment.`\n                        : 'Continue to secure GEN Health checkout for payment, intake, and provider review.'}\n                    </p>\n                  </div>\n                </div>\n                {canPurchase && genCheckout.ok ? (\n                  <a href={genCheckout.url} target=\"_blank\" rel=\"noopener noreferrer\" onClick={event => { if (!event.ctrlKey && !event.metaKey && !event.shiftKey && !event.altKey) { event.preventDefault(); navigateToGenProductFirstCheckout(genCheckout.url); } }} className=\"btn-primary w-full\">\n                    Buy now\n                  </a>\n                ) : (\n                  <button type=\"button\" className=\"btn-primary w-full\" disabled>Temporarily unavailable</button>\n                )}\n                {canPurchase && <button\n                  type=\"button\"\n                  className=\"btn-outline mt-2 w-full\"\n                  onClick={addCurrentToBasket}\n                >\n                  {currentInBasket ? 'Review prescription basket' : 'Save to Care Basket'}\n                </button>}\n                {currentInBasket && (\n                  <button type=\"button\" onClick={openBasket} className=\"btn-ghost mt-2 w-full\">\n                    Open prescription bag\n                  </button>\n                )}\n                <p className=\"mt-3 text-xs text-ink-500 leading-relaxed\">\n                  Add prescriptions to your Care Basket while you shop, then begin intake in GEN Health before product payment. Each prescription continues separately and requires provider review.\n\n                  Purchasing does not guarantee that a prescription will be issued.\n                </p>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <div className=\"container-lux -mt-8 pb-16 lg:-mt-16\">\n        <div className=\"lg:ml-[calc(50%+2rem)] lg:w-[calc(50%-2rem)] border-t border-cream-300 pt-8\">\n          <ProductDescriptionSections product={product} />\n        </div>\n      </div>\n\n      {related.length > 0 && (\n        <section className=\"pb-24\">\n          <div className=\"container-lux\">\n            <h2 className=\"font-serif text-2xl text-ink-900 mb-6\">You may also consider</h2>\n            <div className=\"grid gap-6 sm:grid-cols-2 lg:grid-cols-3\">\n              {related.map((p) => (\n                <ProductCard key={p.id} product={p} />\n              ))}\n            </div>\n          </div>\n        </section>\n      )}\n\n      {recommendationsOpen && (\n        <div\n          className=\"fixed inset-0 z-[70] flex items-center justify-center bg-ink-950/45 px-5 py-8 backdrop-blur-sm animate-fade-in\"\n          onClick={() => setRecommendationsOpen(false)}\n        >\n          <div\n            className=\"max-h-[90vh] w-full max-w-5xl overflow-y-auto rounded-3xl border border-cream-300 bg-cream-50 p-5 shadow-2xl animate-scale-in md:p-7\"\n            role=\"dialog\"\n            aria-modal=\"true\"\n            aria-labelledby=\"family-commonly-purchased-title\"\n            onClick={event => event.stopPropagation()}\n          >\n            <div className=\"flex items-start justify-between gap-4\">\n              <div>\n                <p className=\"text-[10px] font-semibold uppercase tracking-wider-2 text-gold-600\">Added to your prescription bag</p>\n                <h2 id=\"family-commonly-purchased-title\" className=\"mt-1 font-serif text-2xl text-ink-900 md:text-3xl\">Commonly purchased with...</h2>\n                <p className=\"mt-2 max-w-2xl text-sm leading-relaxed text-ink-600\">Explore other provider-reviewed options before checkout. Each prescription is purchased separately through GEN Health and requires its own eligibility review.</p>\n              </div>\n              <button type=\"button\" onClick={() => setRecommendationsOpen(false)} aria-label=\"Close recommendations\" className=\"p-1\">\n                <X size={22} className=\"text-ink-500 hover:text-ink-900\" />\n              </button>\n            </div>\n\n            {orderedRecommendations.length > 0 && (\n              <div className=\"relative mt-6\">\n                <div className=\"grid gap-4 sm:grid-cols-3\">\n                  {orderedRecommendations.map(candidate => {\n                    const candidateRoute = GEN_HOSTED_PRODUCTS[candidate.slug];\n                    if (!candidateRoute) return null;\n                    return (\n                      <Link\n                        key={candidate.slug}\n                        to={`/product/${candidate.slug}`}\n                        onClick={() => setRecommendationsOpen(false)}\n                        className=\"group overflow-hidden rounded-2xl border border-cream-300 bg-white transition-shadow hover:shadow-lg\"\n                      >\n                        <img src={candidate.image} alt={candidate.imageAlt} className=\"aspect-[4/3] w-full object-cover\" />\n                        <div className=\"p-4\">\n                          <p className=\"text-[10px] uppercase tracking-wider text-gold-600\">{candidate.subtitle}</p>\n                          <h3 className=\"mt-1 font-serif text-xl leading-tight text-ink-900 group-hover:text-gold-700\">{candidate.displayName}</h3>\n                          <p className=\"mt-2 text-sm text-ink-500\">Starting at ${candidateRoute.price.toFixed(2)}</p>\n                          <p className=\"mt-3 text-xs font-medium text-gold-700\">View details <span aria-hidden=\"true\">→</span></p>\n                        </div>\n                      </Link>\n                    );\n                  })}\n                </div>\n                {recommendations.length > 1 && (\n                  <div className=\"mt-4 flex items-center justify-center gap-3\">\n                    <button\n                      type=\"button\"\n                      onClick={() => setRecommendationOffset(offset => (offset - 1 + recommendations.length) % recommendations.length)}\n                      aria-label=\"Previous recommendations\"\n                      className=\"rounded-full border border-cream-300 bg-white p-2 text-ink-700 hover:border-gold-400 hover:text-gold-700\"\n                    >\n                      <ChevronLeft size={18} />\n                    </button>\n                    <span className=\"text-xs text-ink-400\">{recommendations.length} prescription options</span>\n                    <button\n                      type=\"button\"\n                      onClick={() => setRecommendationOffset(offset => (offset + 1) % recommendations.length)}\n                      aria-label=\"Next recommendations\"\n                      className=\"rounded-full border border-cream-300 bg-white p-2 text-ink-700 hover:border-gold-400 hover:text-gold-700\"\n                    >\n                      <ChevronRight size={18} />\n                    </button>\n                  </div>\n                )}\n              </div>\n            )}\n\n            <div className=\"mt-7 flex flex-col-reverse gap-2 border-t border-cream-300 pt-5 sm:flex-row sm:justify-end\">\n              <button type=\"button\" onClick={() => setRecommendationsOpen(false)} className=\"btn-ghost w-full sm:w-auto\">Keep shopping</button>\n              <button type=\"button\" onClick={() => { setRecommendationsOpen(false); openBasket(); }} className=\"btn-ghost w-full sm:w-auto\">Review prescription bag</button>\n              <button type=\"button\" onClick={continueToGen} className=\"btn-primary w-full sm:w-auto\">Continue with this prescription</button>\n            </div>\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n\nfunction SelectorChip({\n  selected,\n  onClick,\n  label,\n  disabled,\n}: {\n  selected: boolean;\n  onClick: () => void;\n  label: string;\n  disabled?: boolean;\n}) {\n  return (\n    <button\n      type=\"button\"\n      onClick={onClick}\n      disabled={disabled}\n      aria-pressed={selected}\n      aria-disabled={disabled || undefined}\n      className={`rounded-full px-4 py-2 text-sm border transition-colors ${\n        disabled\n          ? 'border-ink-100 bg-cream-100 text-ink-400 cursor-not-allowed'\n          : selected\n            ? 'border-ink-900 bg-ink-900 text-white'\n            : 'border-ink-200 bg-white text-ink-700 hover:border-ink-400'\n      }`}\n    >\n      {label}\n    </button>\n  );\n}\n"},{"file":"src/components/CareCheckoutReturn.tsx","before":null,"next":"import { useEffect, useRef, useState } from 'react';\nimport { CARE_CHECKOUT_OPENED, validatedCareCheckoutUrl } from '@/lib/commerce/careCheckoutWindow';\n\nexport function CareCheckoutReturn() {\n  const dialog = useRef<HTMLDialogElement>(null);\n  const [url, setUrl] = useState('');\n  useEffect(() => {\n    const opened = (event: Event) => {\n      try {\n        setUrl(validatedCareCheckoutUrl((event as CustomEvent<{ url: string }>).detail.url));\n        dialog.current?.showModal();\n      } catch { /* Ignore invalid destinations. */ }\n    };\n    window.addEventListener(CARE_CHECKOUT_OPENED, opened);\n    return () => window.removeEventListener(CARE_CHECKOUT_OPENED, opened);\n  }, []);\n  return (\n    <dialog ref={dialog} aria-labelledby=\"care-window-title\" className=\"m-auto w-[calc(100%-2rem)] max-w-lg rounded-3xl bg-cream-50 p-7 text-ink-900 shadow-2xl backdrop:bg-black/50\">\n      <h2 id=\"care-window-title\" className=\"font-serif text-2xl\">Your My Bare Method page stays here</h2>\n      <p className=\"mt-4 text-sm leading-relaxed\">Continue in the GEN Health window, then return here when you are ready. On your phone, checkout may open in a new tab.</p>\n      <p className=\"mt-3 text-sm leading-relaxed\">If checkout did not open, use the link below. If it is already open, continue in that window to avoid starting over.</p>\n      {url && <a href={url} target=\"_blank\" rel=\"noopener noreferrer\" className=\"btn-outline mt-4 w-full\">Open GEN Health in a new tab</a>}\n      <p className=\"mt-4 text-xs leading-relaxed text-ink-600\">Returning here does not confirm payment or intake completion. If you already paid, do not pay again. Our team verifies external payments.</p>\n      <a href=\"mailto:info@thebaremethodmn.com\" className=\"mt-3 inline-block text-sm underline\">Get help with your order</a>\n      <button type=\"button\" onClick={() => dialog.current?.close()} className=\"btn-primary mt-5 w-full\">Back to My Bare Method</button>\n    </dialog>\n  );\n}\n"},{"file":"src/lib/commerce/careCheckoutWindow.ts","before":null,"next":"export const CARE_CHECKOUT_OPENED = 'mbm:care-checkout-opened';\n\nexport function validatedCareCheckoutUrl(value: string): string {\n  const url = new URL(value);\n  if (url.origin !== 'https://app.genhealthehr.com' || url.username || url.password ||\n      !/^\\/f5e0mdyBYnDh7HGvek0C\\/product\\/[^/]+$/.test(url.pathname)) {\n    throw new Error('GEN_CHECKOUT_URL_NOT_ALLOWED');\n  }\n  return url.toString();\n}\n\n/** Opens only on a user gesture. A closed/blocked window never means completed care. */\nexport function openCareCheckoutWindow(value: string): void {\n  const url = validatedCareCheckoutUrl(value);\n  try {\n    window.open(url, '_blank', 'popup,width=620,height=820,noopener,noreferrer');\n  } catch {\n    // Some embedded browsers disallow popups; the return dialog provides a normal link.\n  } finally {\n    // noopener may return null even on success; offer an explicit fallback, not a second popup.\n    window.dispatchEvent(new CustomEvent(CARE_CHECKOUT_OPENED, { detail: { url } }));\n  }\n}\n"},{"file":"src/lib/commerce/careCheckoutWindow.test.ts","before":null,"next":"import { afterEach, describe, expect, it, vi } from 'vitest';\nimport { openCareCheckoutWindow, validatedCareCheckoutUrl } from './careCheckoutWindow';\n\nconst url = 'https://app.genhealthehr.com/f5e0mdyBYnDh7HGvek0C/product/lab-example';\nafterEach(() => vi.unstubAllGlobals());\n\ndescribe('hosted care window', () => {\n  it('rejects destinations outside the clinic checkout', () => {\n    for (const value of ['https://evil.example/', url.replace('https:', 'http:'), url.replace('f5e0mdyBYnDh7HGvek0C', 'other'), url.replace('/product/lab-example', '/settings'), url.replace('https://', 'https://user:pass@')]) {\n      expect(() => validatedCareCheckoutUrl(value)).toThrow();\n    }\n  });\n  it.each(['allowed', 'blocked', 'throws'])('preserves main window when popup is %s', mode => {\n    const open = vi.fn(() => { if (mode === 'throws') throw Error('Popup denied'); return null; });\n    const dispatchEvent = vi.fn();\n    const location = { href: 'https://mybaremethod.com/product/example' };\n    vi.stubGlobal('window', { open, dispatchEvent, location, top: { location } });\n    vi.stubGlobal('CustomEvent', class { constructor(public type: string, public options: unknown) {} });\n    expect(() => openCareCheckoutWindow(url)).not.toThrow();\n    expect(open).toHaveBeenCalledTimes(1);\n    expect(open).toHaveBeenCalledWith(url, '_blank', expect.stringContaining('noopener'));\n    expect(location.href).toBe('https://mybaremethod.com/product/example');\n    expect(dispatchEvent).toHaveBeenCalledTimes(1);\n    expect(JSON.stringify(dispatchEvent.mock.calls)).not.toMatch(/paid|completed/);\n  });\n});\n"}];
const hash=s=>crypto.createHash('sha256').update(s.replace(/\r/g,'')).digest('hex');
for(const u of updates){const old=fs.existsSync(u.file)?fs.readFileSync(u.file,'utf8'):null;if(old!==null&&hash(old)===hash(u.next))continue;if((old===null?null:hash(old))!==u.before)throw Error('Source differs; stopped without edits: '+u.file);}
for(const u of updates){fs.mkdirSync(path.dirname(u.file),{recursive:true});fs.writeFileSync(u.file,u.next);console.log('Updated '+u.file);}
